ID = "math_ex_ch6_complexes_4"
R3, R2 = 3 ** .5, 2 ** .5


def figure(a, u, b, ta):
    return plan("Les points A(a), U(u) et B(b), avec b = a/u", f"a = {ta}, u = 1 + i : B est l'image du quotient a/u.",
                [("A", a.real, a.imag, "cyan", "ne"), ("U", u.real, u.imag, "violet", "e"), ("B", b.real, b.imag, "jaune", "e")],
                xs=(-1, 4), ys=(-1, 3) if a.imag < 3 else (-1, 4),
                autres=[{"f": "ligne", "pts": [[0, 0], [p.real, p.imag]], "couleur": c, "trait": "pointille"}
                        for p, c in ((a, "cyan"), (u, "violet"), (b, "jaune"))])


def ass_regles():
    G = [("1", "|z/z′|"), ("2", "arg(z/z′)"), ("3", "arg(z·z′)")]
    D = [("a", "|z|/|z′|"), ("b", "arg z − arg z′ [2π]"), ("c", "arg z + arg z′ [2π]"), ("d", "|z| − |z′|")]
    C = {"1": "a", "2": "b", "3": "c"}
    R = {
      "1-a": ("Oui : le module d'un quotient est le quotient des modules.", "برافو: le module d'un quotient، هو le quotient des modules."),
      "1-b": ("Un module est une longueur, pas un angle.", "لا، le module هو طول، ماشي زاوية."),
      "1-c": ("Un module est une longueur, pas un angle.", "لا، le module هو طول، ماشي زاوية."),
      "1-d": ("On ne soustrait pas les modules d'un quotient : on les divise.", "لا، فـ le quotient ما كنحيدوش les modules، كنقسموهم."),
      "2-a": ("arg(z/z′) est un angle ; |z|/|z′| est une longueur.", "لا، l'argument هو زاوية، و هادي طول."),
      "2-b": ("Oui : dans un quotient, on retire l'angle de z′.", "برافو: فـ le quotient، كنحيدو l'angle ديال z prime."),
      "2-c": ("On ajoute les angles pour un produit ; pour un quotient, on les soustrait.", "لا، كنجمعو les angles فـ le produit. فـ le quotient، كنحيدوهم."),
      "2-d": ("arg(z/z′) est un angle ; |z| − |z′| est une longueur.", "لا، l'argument هو زاوية، و هادي طول."),
      "3-a": ("arg(z·z′) est un angle ; |z|/|z′| est une longueur.", "لا، l'argument هو زاوية، و هادي طول."),
      "3-b": ("Pour un produit, les angles s'ajoutent, ils ne se retirent pas.", "لا، فـ le produit، les angles كيتجمعو، ما كيتحيدوش."),
      "3-c": ("Oui : l'argument d'un produit est la somme des arguments.", "برافو: l'argument d'un produit، هو la somme des arguments."),
      "3-d": ("arg(z·z′) est un angle ; |z| − |z′| est une longueur.", "لا، l'argument هو زاوية، و هادي طول."),
    }
    return association("fa_c4_3", "Plus facile : les règles", "Relie chaque expression à sa règle.",
      "سؤال ساهل: ربط كل expression مع la règle ديالها.", "Relie chaque expression à ce qu'elle vaut.", G, D, C, R,
      ("(1 ; a) (2 ; b) (3 ; c) : |z| − |z′| est de trop.", "un مع a، deux مع b، trois مع c. le module de z، moins le module de z prime، زايد."))


